<script setup lang="ts">
import {ref} from 'vue';const notice=ref('');function submit(e:Event){const form=e.target as HTMLFormElement;const d=new FormData(form);const body=['Name: '+d.get('name'),'Email: '+d.get('email'),'Company: '+d.get('company'),'Phone: '+d.get('phone'),'Topic: '+d.get('topic'),'','Message: '+d.get('message')].join('\n');window.location.href='mailto:santhoshnarayananck@gmail.com?subject='+encodeURIComponent('Portfolio enquiry: '+d.get('topic'))+'&body='+encodeURIComponent(body);notice.value='Your email app should open with your enquiry ready to send.'}
</script><template><form class="contact-form" @submit.prevent="submit"><div class="eyebrow">START A CONVERSATION</div><div class="form-grid"><label>Name<input name="name" autocomplete="name" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Company<input name="company" autocomplete="organization" required></label><label>Phone <small>(optional)</small><input name="phone" type="tel" autocomplete="tel"></label><label class="full">What would you like to discuss?<select name="topic" required><option value="" selected disabled>Select a topic</option><option>Job opportunity</option><option>Project collaboration</option><option>Technical consultation</option><option>Other</option></select></label><label class="full">Message<textarea name="message" required></textarea></label><button type="submit" class="pill primary full">Prepare email ↗</button><p class="form-note full" role="status">{{notice || 'Opens your email app with the message ready to send.'}}</p></div><div class="contact-options"><a href="https://wa.me/919025985363?text=Hi%20Santhosh%2C%20I%20found%20your%20portfolio%20and%20would%20like%20to%20connect.">Message me on WhatsApp ↗</a><a href="mailto:santhoshnarayananck@gmail.com?subject=Let%27s%20connect">Email me ↗</a></div></form></template>
